// Verbatim acceptance prompt supplied by the user; never sent to a live model by tests.
export const exactAcceptancePrompt='Synthetic planning test: reduce company-wide annualized voluntary turnover by 20% relative, from an accepted 8.2% baseline to a 6.56% target, within 12 months. This is a relative reduction, not 20 percentage points. Use a maximum one-time programme budget of $500,000 USD as a cap, not assumed spending, and existing HR and manager capacity without adding headcount. Scope: all countries and all business units. Treat the baseline, target, budget, timeline and capacity as accepted editable planning assumptions, not verified company facts. Propose three Action Plan alternatives, each with the most effective relevant combination of retention interventions supported by the available evidence. Combine manager practices, targeted retention actions, career growth or internal mobility, learning and workload or process changes where relevant; do not force every method into every plan. Preserve the reduction objective and these constraints.';
export const exactAcceptanceGoal='Reduce annualized voluntary turnover by 20% relative within 12 months';
// Explicit proposed changes plus supporting diagnostics; never evidence of live generation quality.
export function deliveryAcceptanceWire(goal){
 const alternatives=[['A','Manager conversation pilot','Pilot manager stay conversations with a shared discussion guide and review employee feedback with HR.','Introduce a stay-conversation guide and run manager practice sessions for the reviewed pilot group.','HR partner','manager_workload'],['B','Career development pilot','Run career development conversations and internal mentoring sessions, then review participant feedback with HR.','Run career development conversations and internal mentoring sessions for employees in the reviewed pilot group.','Learning lead','learning'],['C','Workload practice pilot','Pilot team workload prioritization meetings and protected focus periods, then review delivery and employee feedback.','Introduce team workload prioritization meetings and protected focus periods for the reviewed pilot group.','Business owner','manager_workload']];
 return {version:1,goal,bundles:alternatives.map(([id,name,objective,firstStep,ownerRole,domain])=>({id,name,objective,coordination:'Use participant feedback to review the proposed practice before considering expansion.',components:{c1:{name,domain,firstStep,ownerRole,activity:'delivery',dependsOn:[],evidence:['W1:summary'],limitation:'Proposed change requiring review; evidence does not establish a retention effect.'},c2:{name:'Pilot feedback review',domain:'execution',firstStep:'Review participant feedback and practice uptake with the proposed owner before considering adjustments.',ownerRole:'HR partner',activity:'diagnostic',dependsOn:['c1'],evidence:['W1:summary'],limitation:'Review does not prove causation or authorize expansion.'}},limitation:'Use existing capacity subject to review; costs, timing, feasibility and comparative effectiveness remain unproven.'})),question:null,unavailableReason:null};
}
